import { describe, it } from "node:test";
import * as assert from "node:assert";
import {
  validateApiKey,
  requireApiKey,
  getProxyUrl,
  getEnvForTarget,
  buildOpenClawPatch,
  deepMerge,
  checkConnectivity,
  DEFAULT_PROXY_URL,
} from "./config.ts";

describe("validateApiKey", () => {
  it("accepts valid API keys", () => {
    assert.strictEqual(validateApiKey("duel_abcd1234_abcdefghijklmnopqrstuvwxyz123456"), true);
    assert.strictEqual(validateApiKey("duel_ABCD1234_ABCDEFGHIJKLMNOPQRSTUVWXYZ123456"), true);
    assert.strictEqual(validateApiKey("duel_12345678_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"), true);
  });

  it("rejects invalid API keys", () => {
    assert.strictEqual(validateApiKey(null), false);
    assert.strictEqual(validateApiKey(undefined), false);
    assert.strictEqual(validateApiKey(""), false);
    assert.strictEqual(validateApiKey("duel_short_key"), false);
    assert.strictEqual(validateApiKey("notduel_abcd1234_abcdefghijklmnopqrstuvwxyz123456"), false);
    assert.strictEqual(validateApiKey("duel_abcd1234"), false);
    assert.strictEqual(validateApiKey("duel_abcd1234_tooshortkey"), false);
  });
});

describe("requireApiKey", () => {
  it("returns valid key", () => {
    const key = "duel_abcd1234_abcdefghijklmnopqrstuvwxyz123456";
    assert.strictEqual(requireApiKey(key), key);
  });

  it("throws for invalid key", () => {
    assert.throws(() => requireApiKey("invalid"), /DUEL_API_KEY/);
    assert.throws(() => requireApiKey(null), /DUEL_API_KEY/);
    assert.throws(() => requireApiKey(undefined), /DUEL_API_KEY/);
  });

  it("uses custom label in error", () => {
    assert.throws(() => requireApiKey("invalid", "CUSTOM_KEY"), /CUSTOM_KEY/);
  });
});

describe("getProxyUrl", () => {
  it("uses environment variable if set", () => {
    process.env.DUEL_PROXY_URL = "https://custom.example.com/v1";
    const url = getProxyUrl();
    assert.strictEqual(url, "https://custom.example.com/v1");
    delete process.env.DUEL_PROXY_URL;
  });

  it("removes trailing slash", () => {
    process.env.DUEL_PROXY_URL = "https://example.com/v1/";
    const url = getProxyUrl();
    assert.strictEqual(url, "https://example.com/v1");
    delete process.env.DUEL_PROXY_URL;
  });

  it("uses default when not set", () => {
    delete process.env.DUEL_PROXY_URL;
    const url = getProxyUrl();
    assert.strictEqual(url, DEFAULT_PROXY_URL);
  });

  it("validates URL format", () => {
    process.env.DUEL_PROXY_URL = "not-a-valid-url";
    assert.throws(() => getProxyUrl(), /valid URL/);
    delete process.env.DUEL_PROXY_URL;
  });
});

describe("getEnvForTarget", () => {
  const apiKey = "duel_abcd1234_abcdefghijklmnopqrstuvwxyz123456";
  const proxyUrl = "https://example.com/v1";

  it("returns DUEL keys for claude-code", () => {
    const env = getEnvForTarget("claude-code", apiKey, proxyUrl);
    assert.strictEqual(env.DUEL_API_KEY, apiKey);
    assert.strictEqual(env.DUEL_PROXY_URL, proxyUrl);
  });

  it("returns DUEL keys for cursor", () => {
    const env = getEnvForTarget("cursor", apiKey, proxyUrl);
    assert.strictEqual(env.DUEL_API_KEY, apiKey);
    assert.strictEqual(env.DUEL_PROXY_URL, proxyUrl);
  });

  it("returns OPENAI_API_KEY for codex", () => {
    const env = getEnvForTarget("codex", apiKey, proxyUrl);
    assert.strictEqual(env.OPENAI_API_KEY, apiKey);
    assert.strictEqual(env.OPENAI_API_BASE, proxyUrl);
  });

  it("returns OPENAI_API_KEY for openai-compat", () => {
    const env = getEnvForTarget("openai-compat", apiKey, proxyUrl);
    assert.strictEqual(env.OPENAI_API_KEY, apiKey);
    assert.strictEqual(env.OPENAI_API_BASE, proxyUrl);
  });

  it("validates API key", () => {
    assert.throws(() => getEnvForTarget("claude-code", "invalid_key", proxyUrl), /DUEL_API_KEY/);
  });
});

describe("buildOpenClawPatch", () => {
  const apiKey = "duel_abcd1234_abcdefghijklmnopqrstuvwxyz123456";
  const proxyUrl = "https://example.com/v1";

  it("builds patch with provider config", () => {
    const patch = buildOpenClawPatch(apiKey, proxyUrl) as Record<string, unknown>;
    assert.ok(patch.agents !== undefined);
  });

  it("references API key as template variable", () => {
    const patch = buildOpenClawPatch(apiKey, proxyUrl);
    const patchStr = JSON.stringify(patch);
    assert.match(patchStr, /\$\{DUEL_API_KEY\}/);
    // Should NOT contain plaintext key
    assert.ok(!patchStr.includes(apiKey));
  });

  it("validates API key", () => {
    assert.throws(() => buildOpenClawPatch("invalid_key", proxyUrl), /DUEL_API_KEY/);
  });
});

describe("deepMerge", () => {
  it("merges simple objects", () => {
    const base = { a: 1, b: 2 };
    const patch = { b: 3, c: 4 };
    const result = deepMerge(base, patch);
    assert.deepStrictEqual(result, { a: 1, b: 3, c: 4 });
  });

  it("replaces arrays", () => {
    const base = { a: [1, 2, 3] };
    const patch = { a: [4, 5] };
    const result = deepMerge(base, patch);
    assert.deepStrictEqual(result, { a: [4, 5] });
  });

  it("recursively merges nested objects", () => {
    const base = { a: { b: 1, c: 2 }, d: 3 };
    const patch = { a: { c: 3, e: 4 } };
    const result = deepMerge(base, patch);
    assert.deepStrictEqual(result, { a: { b: 1, c: 3, e: 4 }, d: 3 });
  });

  it("replaces scalars", () => {
    const base = { a: "hello" };
    const patch = { a: "world" };
    const result = deepMerge(base, patch);
    assert.deepStrictEqual(result, { a: "world" });
  });
});

describe("checkConnectivity", async () => {
  const apiKey = "duel_abcd1234_abcdefghijklmnopqrstuvwxyz123456";

  it("returns error for invalid key format", async () => {
    const result = await checkConnectivity("invalid_key", "https://example.com/v1");
    assert.strictEqual(result.status, "invalid_key");
    assert.strictEqual(result.ok, false);
  });

  it("returns unreachable for connection failure", async () => {
    const result = await checkConnectivity(apiKey, "https://localhost:9999/v1");
    assert.strictEqual(result.status, "unreachable");
