        return {
          ok: false,
          status: \"unauthorized\",
          message: \"API key is not authorized\",
          httpStatus: response.status,
        };
      }
    } catch (err) {
      // Continue to next endpoint or return unreachable
    }
  }

  return {
    ok: false,
    status: \"unreachable\",
    message: \"Could not reach the API\",
  };
}
